def transform(grid):
    block_size = 3
    height = len(grid) // block_size
    width = len(grid[0]) // block_size
    return [
        [next((grid[r][c]
               for r in range(block_row * block_size, (block_row + 1) * block_size)
               for c in range(block_col * block_size, (block_col + 1) * block_size)
               if grid[r][c] not in (0, 5)), 0)
         for block_col in range(width)]
        for block_row in range(height)
    ]
